<?php
namespace App\Filament\Resources\Gemstones;
use App\Filament\Resources\Concerns\AdminResource; use App\Filament\Resources\Gemstones\Pages\ManageGemstones; use App\Models\Gemstone;
use BackedEnum; use Filament\Actions\BulkActionGroup; use Filament\Actions\DeleteAction; use Filament\Actions\DeleteBulkAction; use Filament\Actions\EditAction; use Filament\Forms\Components\TextInput; use Filament\Schemas\Schema; use Filament\Support\Icons\Heroicon; use Filament\Tables\Columns\TextColumn; use Filament\Tables\Table;
class GemstoneResource extends AdminResource { protected static ?string $model = Gemstone::class; protected static string $viewPermission='catalog.view'; protected static ?string $managePermission='catalog.update'; protected static string|BackedEnum|null $navigationIcon=Heroicon::OutlinedSparkles; protected static ?string $navigationLabel='Đá quý'; protected static string|\UnitEnum|null $navigationGroup='Sản phẩm'; protected static ?int $navigationSort=50; public static function form(Schema $s): Schema{return $s->components([TextInput::make('name')->label('Tên')->required()->unique(ignoreRecord:true),TextInput::make('hardness_mohs')->label('Độ cứng Mohs')->numeric()->minValue(0)->maxValue(10)]);} public static function table(Table $t):Table{return $t->columns([TextColumn::make('name')->label('Tên')->searchable(),TextColumn::make('hardness_mohs')->label('Mohs')->numeric()])->recordActions([EditAction::make()->label('Sửa'),DeleteAction::make()->label('Xóa')])->toolbarActions([BulkActionGroup::make([DeleteBulkAction::make()])]);} public static function getPages():array{return ['index'=>ManageGemstones::route('/')];} }
